def build(b):
    for level in range(1, 6):
        for prompt, correct, wrong, expl in MC[level]:
            b.mc(M, level, prompt, correct, wrong, expl)
        for prompt, word, ans, hint, expl in WRITE[level]:
            b.write(M, level, prompt, ans, hint, expl, word=word)
        for s in DICTATION[level]:
            b.write(M, level, "Listen and write the sentence", s, f"It has {len(s.split())} words",
                    "Remember the capital letter at the start and the punctuation at the end.", dictation=True)
        for words in ORDER[level]:
            b.order(M, level, "Put the words in order to make a sentence", words, ' '.join(words))
